#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include "mmt_lib.h"

/* ---- EDIT THESE FOR YOUR INSTALL ---- */
/* Absolute path to the 5g-ml-scorer folder shipped next to this repo's rules/. It must contain
   a .venv (see its README), the .env with your Kafka settings, and event_watch.py. */
#define SCORER_DIR       "/home/pqv/Documents/tools/mmt-security/5g-ml-scorer"
#define SCORER_MODEL     "models/rf_event_multiclass.joblib"   /* relative to SCORER_DIR */
#define SCORER_WATCH_DIR "/tmp/mmt-events"                     /* = mmt-probe file-output.output-dir */
#define SCORER_ALERTS    "/home/pqv/Documents/results/replay-alerts.log"   /* mkdir this folder first! */
/* ------------------------------------- */
/* Kafka broker + SASL credentials are NOT set here: they live in the .env file inside
   SCORER_DIR, which stix_kafka.py reads on startup. Nothing to edit in this rule. */

/* Throttle: attempt a (re)launch at most once every 30s. The lock file inside event_watch.py
   guarantees only one scorer actually runs; this just avoids spawning bash on every packet. */
static time_t _last_launch = 0;

/* Takes one (ignored) argument: the mmt-security compiler needs >=1 arg for #func(...). */
static int em_launch_5g_scorer(int nas_msg_type) {
    (void) nas_msg_type;
    time_t now = time(NULL);
    if (now - _last_launch < 30) return 1;   /* already attempted recently */
    _last_launch = now;
    system("bash -c '"
           "cd " SCORER_DIR " && "
           "source .venv/bin/activate && "               /* the venv with pandas/scikit-learn/joblib */
           "nohup python3 event_watch.py "
             "--model " SCORER_MODEL " "                 /* multi-class model: predicts the attack family */
             "--watch-dir " SCORER_WATCH_DIR " "
             "--lock-file /tmp/mmt-event-scorer.lock "
             "--idle-timeout 60 "
             "--alerts " SCORER_ALERTS " "
             "--kafka "                                   /* publish each alert as a STIX 2.1 bundle */
           ">> /home/pqv/Documents/results/scorer.out 2>&1 &'");
    return 1;
}
